import { useEffect, useState } from "react";
import type { ReactNode } from "react";
import { api } from "../../api";
import { Icon } from "../../Icon";
import { ConfirmActionDialog, IntelligenceUnavailableBoundary } from "../../intelligence/IntelligencePrimitives";
import { loadProposal, proposalCommand, proposalHeaders } from "./api";
import { asList, asRecord, control, currentStageNumber, displayDate, field, labelize, text } from "./helpers";
import { sourceLabels } from "./registry";
import { lifecycleStages, type JsonRecord, type ProposalDetail, type ProposalRole } from "./types";

const ownerRoles = new Set<ProposalRole>(["SYSTEM_ADMIN", "OWNER_SPONSOR", "COMMERCIAL_APPROVER"]);
const engineeringRoles = new Set<ProposalRole>(["SYSTEM_ADMIN", "OWNER_SPONSOR", "RESPONSIBLE_ENGINEER"]);

export function ProposalWorkspacePage({ role, proposalId, onBack }: { role: ProposalRole; proposalId: string; onBack: () => void }) {
  const [proposal, setProposal] = useState<ProposalDetail | null>(null);
  const [activeSection, setActiveSection] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");
  const [dialog, setDialog] = useState<{ title: string; consequence: string; confirmLabel: string; action: () => Promise<void> } | null>(null);
  const refresh = async () => { setLoading(true); try { setProposal(await loadProposal(role, proposalId)); setError(""); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Proposal workspace unavailable."); } finally { setLoading(false); } };
  useEffect(() => { void refresh(); }, [proposalId, role]);
  useEffect(() => { const onHash = () => { const value = Number(window.location.hash.replace("#stage-", "")); if (value >= 1 && value <= 5) setActiveSection(value); }; onHash(); window.addEventListener("hashchange", onHash); return () => window.removeEventListener("hashchange", onHash); }, []);
  const execute = async (action: () => Promise<void>) => { setDialog(null); setMessage(""); setError(""); try { await action(); await refresh(); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "The Proposal action was not completed."); } };
  const requestAction = (title: string, consequence: string, confirmLabel: string, action: () => Promise<void>) => setDialog({ title, consequence, confirmLabel, action });
  if (loading && !proposal) return <div className="proposal-feature-page"><div className="proposal-loading panel" role="status"><Icon name="refresh" size={18} /> Loading Proposal workspace…</div></div>;
  if (!proposal) return <div className="proposal-feature-page"><div className="proposal-alert error-state" role="alert"><Icon name="alert" size={18} /> {error || "Proposal not found."}<button type="button" className="button-secondary" onClick={onBack}>Return to Proposals</button></div></div>;
  const stageNumber = currentStageNumber(proposal.stage);
  return <div className="proposal-feature-page proposal-workspace-page">
    <header className="proposal-workspace-header"><div><button type="button" className="text-button proposal-back-button" onClick={onBack}><Icon name="arrow-left" size={14} /> Proposal register</button><span className="eyebrow">PROPOSAL WORKSPACE</span><h2>{proposal.title}</h2><div className="proposal-identity-line"><b>{proposal.proposal_reference}</b><span>Client · {text(proposal.client_name)}</span><span>Project · {text(proposal.project_reference, "Provisional")}</span></div></div><div className="proposal-header-state"><span className="tag">{proposal.stage_label}</span><b>Owner · {proposal.current_owner}</b><small>Last activity · {displayDate(proposal.last_activity)}</small></div></header>
    {(message || error) && <div className={error ? "proposal-alert error-state" : "proposal-alert inline-message"} role={error ? "alert" : "status"}><Icon name={error ? "alert" : "check"} size={16} /> <span>{error || message}</span>{error && <button type="button" className="text-button" onClick={() => setError("")}>Dismiss</button>}</div>}
    <Lifecycle current={stageNumber} active={activeSection} onSelect={(number) => { setActiveSection(number); window.history.replaceState({}, "", `${window.location.pathname}#stage-${number}`); }} />
    <div className="proposal-workspace-grid"><main className="proposal-stage-main"><StageHeading stage={lifecycleStages[activeSection - 1]} current={stageNumber} /><StageContent proposal={proposal} role={role} activeSection={activeSection} stageNumber={stageNumber} setProposal={setProposal} setMessage={setMessage} setError={setError} requestAction={requestAction} refresh={refresh} /></main><AttentionRail proposal={proposal} stageNumber={stageNumber} onSelect={(number) => { setActiveSection(number); window.location.hash = `stage-${number}`; }} /></div>
    {dialog && <ConfirmActionDialog title={dialog.title} consequence={dialog.consequence} confirmLabel={dialog.confirmLabel} onCancel={() => setDialog(null)} onConfirm={() => void execute(dialog.action)} />}
  </div>;
}

function Lifecycle({ current, active, onSelect }: { current: number; active: number; onSelect: (number: number) => void }) {
  return <nav className="proposal-lifecycle" aria-label="Proposal lifecycle">{lifecycleStages.map((stage) => { const state = stage.number < current ? "complete" : stage.number === current ? "current" : "future"; return <button type="button" key={stage.number} className={`proposal-lifecycle-step ${state} ${active === stage.number ? "selected" : ""}`} aria-current={active === stage.number ? "step" : undefined} onClick={() => onSelect(stage.number)}><span className="proposal-step-number">{state === "complete" ? "✓" : stage.number}</span><span><b>{stage.label}</b><small>{state === "current" ? "Current workspace" : state === "complete" ? "Completed · inspect" : "Future stage"}</small></span></button>; })}</nav>;
}

function StageHeading({ stage, current }: { stage: typeof lifecycleStages[number]; current: number }) {
  return <div className="proposal-stage-heading"><div><span className="eyebrow">STAGE {stage.number} · {stage.label.toUpperCase()}</span><h3>{stage.description}</h3></div><span className={stage.number === current ? "proposal-stage-pill current" : "proposal-stage-pill"}>{stage.number === current ? "Current stage" : stage.number < current ? "Completed · read-only review" : "Future stage"}</span></div>;
}

function StageContent({ proposal, role, activeSection, stageNumber, setProposal, setMessage, setError, requestAction, refresh }: { proposal: ProposalDetail; role: ProposalRole; activeSection: number; stageNumber: number; setProposal: (proposal: ProposalDetail) => void; setMessage: (value: string) => void; setError: (value: string) => void; requestAction: (title: string, consequence: string, label: string, action: () => Promise<void>) => void; refresh: () => Promise<void> }) {
  if (activeSection === 1) return <IntakeStage proposal={proposal} role={role} stageNumber={stageNumber} setProposal={setProposal} setMessage={setMessage} setError={setError} requestAction={requestAction} refresh={refresh} />;
  if (activeSection === 2) return <EngineeringStage proposal={proposal} role={role} stageNumber={stageNumber} setProposal={setProposal} setMessage={setMessage} setError={setError} requestAction={requestAction} refresh={refresh} />;
  if (activeSection === 3) return <CommercialStage proposal={proposal} role={role} stageNumber={stageNumber} setProposal={setProposal} setMessage={setMessage} setError={setError} requestAction={requestAction} refresh={refresh} />;
  if (activeSection === 4) return <ClientResponseStage proposal={proposal} role={role} stageNumber={stageNumber} setProposal={setProposal} setMessage={setMessage} setError={setError} requestAction={requestAction} refresh={refresh} />;
  return <HandoffStage proposal={proposal} role={role} stageNumber={stageNumber} setProposal={setProposal} setMessage={setMessage} setError={setError} requestAction={requestAction} refresh={refresh} />;
}

function StagePanel({ eyebrow, title, description, children }: { eyebrow: string; title: string; description?: string; children: ReactNode }) {
  return <section className="proposal-surface panel"><div className="panel-head"><div><span className="eyebrow">{eyebrow}</span><h3>{title}</h3></div>{description && <small>{description}</small>}</div>{children}</section>;
}

function IntakeStage({ proposal, role, stageNumber, setProposal, setMessage, setError, requestAction, refresh }: StageProps) {
  const [client, setClient] = useState(field(proposal, "client_name", proposal.client_name || "")); const [description, setDescription] = useState(field(proposal, "project_description", proposal.title)); const [scope, setScope] = useState(field(proposal, "client_scope_of_work")); const [note, setNote] = useState("");
  const save = async () => { try { const result = await api<ProposalDetail>(`/api/bd/proposals/${proposal.id}`, { method: "PATCH", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ fields: { ...proposal.fields, client_name: client, project_description: description, client_scope_of_work: scope }, expected_updated_at: proposal.updated_at }) }); setProposal(result); setMessage("Intake context saved and read back from the Proposal service."); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Intake could not be saved."); } };
  const addNote = async () => { if (!note.trim()) return; try { const result = await api<ProposalDetail>(`/api/bd/proposals/${proposal.id}/notes`, { method: "POST", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ note_type: "CLIENT_CLARIFICATION", content: note.trim() }) }); setProposal(result); setNote(""); setMessage("Client clarification saved as human-entered context."); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Note could not be saved."); } };
  const proceed = async () => { const result = await api<JsonRecord>(`/api/bd/proposals/${proposal.id}/proceed`, { method: "POST", headers: proposalHeaders(role) }); if (result.proposal && typeof result.proposal === "object") setProposal(result.proposal as ProposalDetail); setMessage("Intake completed. Engineering Preparation is now the next step."); };
  return <><StagePanel eyebrow="SOURCE / EVIDENCE CENTER" title="Evidence Center" description="Actual source records remain distinct from human notes and machine candidates."><EvidenceCenter proposal={proposal} role={role} setProposal={setProposal} setMessage={setMessage} setError={setError} /></StagePanel><StagePanel eyebrow="CLIENT / REQUEST" title="Client and Proposal context" description="Editable before Engineering handoff; canonical identity stays server-owned."><div className="proposal-form-grid"><label>Client<input value={client} onChange={(event) => setClient(event.target.value)} /></label><label>Proposal contact<input value={text(asRecord(proposal.forms_v2).proposal_contact && asRecord(asRecord(proposal.forms_v2).proposal_contact).display_name, "Not recorded")} readOnly /></label><label className="proposal-form-wide">Client requested scope<textarea value={scope} onChange={(event) => setScope(event.target.value)} /></label><label className="proposal-form-wide">Project description<textarea value={description} onChange={(event) => setDescription(event.target.value)} /></label></div><div className="proposal-actions"><button type="button" className="button-secondary" onClick={() => void save()}>Save intake context</button></div></StagePanel><SiteAndPeople proposal={proposal} role={role} setProposal={setProposal} setMessage={setMessage} setError={setError} /><StagePanel eyebrow="CONVERSATIONS / OPEN ITEMS" title="Notes, unknowns, and conflicts" description="Unknown ≠ conflict ≠ assumption. Human context is not verified evidence."><OpenItems proposal={proposal} /><div className="proposal-inline-form"><input aria-label="Client clarification note" placeholder="Add a call, meeting, or client clarification note" value={note} onChange={(event) => setNote(event.target.value)} /><button type="button" className="button-secondary" onClick={() => void addNote()} disabled={!note.trim()}>Add note</button></div></StagePanel><ReadinessCard proposal={proposal} role={role} stageNumber={stageNumber} onProceed={() => requestAction("Proceed to Engineering Preparation", "This records the human handoff from Intake & Sources. It does not confirm scope or authorize commercial activity.", "Proceed to Engineering", proceed)} refresh={refresh} /></>;
}

function EvidenceCenter({ proposal, role, setProposal, setMessage, setError }: Pick<StageProps, "proposal" | "role" | "setProposal" | "setMessage" | "setError">) {
  const [sourceType, setSourceType] = useState("TENDER_DOCUMENT"); const [file, setFile] = useState<File | null>(null); const [busy, setBusy] = useState(false);
  const upload = async () => { if (!file) return; setBusy(true); const body = new FormData(); body.append("source_type", sourceType); body.append("file", file); try { const result = await api<JsonRecord>(`/api/bd/proposals/${proposal.id}/sources`, { method: "POST", headers: proposalHeaders(role), body }); if (result.proposal && typeof result.proposal === "object") setProposal(result.proposal as ProposalDetail); setFile(null); setMessage(`${sourceLabels[sourceType] || labelize(sourceType)} registered in the Evidence Center.`); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Evidence could not be registered."); } finally { setBusy(false); } };
  const sources = proposal.sources || [];
  return <><div className="evidence-summary"><b>{sources.length} source record{sources.length === 1 ? "" : "s"}</b><span>Currentness, classification, and provenance are available on each record.</span></div><div className="evidence-record-list">{sources.map((source, index) => <article className="evidence-record" key={text(source.id, `source-${index}`)}><div className="evidence-record-icon"><Icon name="library" size={18} /></div><div><b>{text(source.source_title ?? source.source_filename, "Untitled source")}</b><span>{sourceLabels[text(source.source_type, "")] || labelize(source.source_type)} · {text(source.verification_state ?? source.status, "Observed")}</span><small>DocumentVersion · {text(source.document_version_id ?? source.source_revision, "Not captured")} · {displayDate(source.created_at)}</small></div><span className="evidence-state">{text(source.currentness_state ?? source.status, "CURRENT")}</span></article>)}{!sources.length && <div className="proposal-empty-inline"><Icon name="empty" size={17} /><span>No source evidence yet. Add the first record or continue without a source.</span></div>}</div><div className="proposal-inline-form evidence-add"><select aria-label="Evidence source family" value={sourceType} onChange={(event) => setSourceType(event.target.value)}><option value="TENDER_EMAIL">Tender Email</option><option value="TENDER_DOCUMENT">Tender Document</option><option value="TENDER_PHOTO">Tender Photo / Image</option><option value="CLIENT_DATA">Client Information</option></select><input aria-label="Evidence file" type="file" accept={sourceType === "TENDER_PHOTO" ? "image/*" : undefined} onChange={(event) => setFile(event.target.files?.[0] || null)} /><button type="button" className="button-secondary" onClick={() => void upload()} disabled={busy || !file}>{busy ? "Registering…" : "Add source evidence"}</button></div></>;
}

function SiteAndPeople({ proposal, role, setProposal, setMessage, setError }: Pick<StageProps, "proposal" | "role" | "setProposal" | "setMessage" | "setError">) {
  const site = asRecord(asRecord(proposal.forms_v2).site_context); const [location, setLocation] = useState(text(site.location_text, "")); const [area, setArea] = useState(text(site.area_value, "")); const [areaKind, setAreaKind] = useState(text(site.area_kind, "NOT_SPECIFIED"));
  const save = async () => { try { const result = await api<ProposalDetail>(`/api/bd/proposals/${proposal.id}/site-context`, { method: "PUT", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ location_text: location, area_value: area || undefined, area_kind: areaKind }) }); setProposal(result); setMessage("Site and property context saved."); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Site context could not be saved."); } };
  return <StagePanel eyebrow="SITE / PROPERTY / STAKEHOLDERS" title="Site and client context" description="Area basis is explicit; blank is not silently treated as N/A."><div className="proposal-form-grid"><label>Location<input value={location} onChange={(event) => setLocation(event.target.value)} /></label><label>Plot / property reference<input value={text(site.property_reference, "")} onChange={() => undefined} readOnly /></label><label>Area value<input value={area} onChange={(event) => setArea(event.target.value)} /></label><label>Area basis<select value={areaKind} onChange={(event) => setAreaKind(event.target.value)}><option value="GROSS">Gross</option><option value="NET">Net</option><option value="PLOT">Plot</option><option value="BUILT_UP">Built-up</option><option value="OTHER">Other</option><option value="NOT_SPECIFIED">Not specified</option></select></label><label className="proposal-form-wide">Site description<textarea value={text(site.site_description, "")} readOnly /></label></div><p className="muted">{asList(asRecord(proposal.forms_v2).stakeholders).length} stakeholder record(s) · {proposal.site_photos?.length || 0} site/project photo(s)</p><button type="button" className="button-secondary" onClick={() => void save()}>Save site context</button></StagePanel>;
}

function OpenItems({ proposal }: { proposal: ProposalDetail }) { const hardening = asRecord(proposal.hardening); const items: Array<JsonRecord & { kind: string }> = [...asList(hardening.unknowns).map((item) => ({ ...item, kind: "Unknown" })), ...asList(hardening.conflicts).map((item) => ({ ...item, kind: "Conflict" })), ...asList(hardening.assumptions).map((item) => ({ ...item, kind: "Assumption" }))]; return <div className="open-item-list">{items.length ? items.map((item, index) => <div key={text(item.id, `open-item-${index}`)}><span className="proposal-mini-label">{item.kind}</span><b>{text(item.statement ?? item.field_code, "Open item")}</b><small>{labelize(item.materiality ?? item.status)}</small></div>) : <div className="proposal-empty-inline">No unknowns, conflicts, or assumptions recorded.</div>}</div>; }

function EngineeringStage({ proposal, role, stageNumber, setProposal, setMessage, setError, requestAction, refresh }: StageProps) {
  const forms = asRecord(proposal.forms_v2); const [scope, setScope] = useState(field(proposal, "scope_of_work", field(proposal, "sow", ""))); const [process, setProcess] = useState(field(proposal, "process_of_work", "")); const assessment = control(proposal, "technical_assessment"); const scopeConfirmation = control(proposal, "scope_confirmation");
  const save = async () => { try { const result = await api<ProposalDetail>(`/api/bd/proposals/${proposal.id}`, { method: "PATCH", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ fields: { ...proposal.fields, scope_of_work: scope, process_of_work: process }, expected_updated_at: proposal.updated_at }) }); setProposal(result); setMessage("Engineering preparation saved."); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Engineering preparation could not be saved."); } };
  const assess = async () => { await api(`/api/bd/proposals/${proposal.id}/technical-assessments`, { method: "POST", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ status: "PASS", findings: [{ code: "TECHNICAL_REVIEW", disposition: "PASS", note: "Technical evidence reviewed by the responsible engineer." }], source_lineage: { proposal_id: proposal.id } }) }); setMessage("Technical assessment recorded."); };
  const confirmScope = async () => { await api(`/api/bd/proposals/${proposal.id}/scope-confirmations`, { method: "POST", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ scope_statement: scope, service_offering_codes: ["PERMITTING"] }) }); setMessage("AMEC Scope confirmed by a human operator."); };
  const eligible = async () => { await api(`/api/bd/proposals/${proposal.id}/service-eligibility`, { method: "POST", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ service_offering_code: "PERMITTING", result: "ELIGIBLE", capability_reference: "configured-service-catalog", policy_reference: "configured-policy" }) }); setMessage("Service eligibility recorded from governed configuration."); };
  const ready = async () => { await api(`/api/proposals-main/proposals/${proposal.id}/engineering-ready`, { method: "POST", headers: proposalHeaders(role) }); setMessage("Engineering is ready for Commercial Review."); };
  return <><StagePanel eyebrow="CLIENT REQUEST" title="Pinned request context" description="The original client request remains visible while Engineering prepares AMEC interpretation."><div className="pinned-context"><b>{field(proposal, "client_scope_of_work", "Client scope not recorded")}</b><span>{field(proposal, "project_description", proposal.title)}</span><small>{proposal.sources.length} linked source record(s) · client context is not the confirmed AMEC Scope.</small></div></StagePanel><StagePanel eyebrow="TECHNICAL / SITE ASSESSMENT" title="Engineering review" description="Human technical assessment is separate from Scope confirmation."><div className="decision-grid"><DecisionStatus label="Assessment" value={text(assessment?.status, "Not recorded")} /><DecisionStatus label="Reviewer" value={text(assessment?.assessed_by, "Responsible Engineer")}/><DecisionStatus label="Linked evidence" value={`${proposal.sources.length} source record(s)`}/></div>{engineeringRoles.has(role) ? <button type="button" className="button-secondary" onClick={() => requestAction("Record technical assessment", "This records the human Engineering assessment. It does not confirm commercial scope or service eligibility.", "Record assessment", assess)}>Record PASS assessment</button> : <p className="muted">Engineering assessment is read-only for this persona.</p>}</StagePanel><StagePanel eyebrow="AMEC TECHNICAL INTERPRETATION" title="Scope comparison" description="Client requested scope, AMEC interpretation, and confirmed commercial scope remain distinct."><div className="scope-comparison"><div><span>Client requested scope</span><p>{field(proposal, "client_scope_of_work")}</p></div><div><span>AMEC technical interpretation</span><textarea aria-label="AMEC technical interpretation" value={scope} onChange={(event) => setScope(event.target.value)} readOnly={!engineeringRoles.has(role)} /></div><div><span>Confirmed commercial scope</span><p>{text(scopeConfirmation?.scope_statement, "Not confirmed")}</p></div></div><label>Engineering process of work<textarea aria-label="Engineering process of work" value={process} onChange={(event) => setProcess(event.target.value)} readOnly={!engineeringRoles.has(role)} /></label>{engineeringRoles.has(role) && <button type="button" className="button-secondary" onClick={() => void save()}>Save technical interpretation</button>}</StagePanel><StagePanel eyebrow="GOVERNED SERVICE DECISION" title="Scope confirmation and service eligibility" description="Business/system controls remain authoritative; opaque fixture references are not shown."><div className="decision-grid"><DecisionStatus label="Scope confirmation" value={text(scopeConfirmation?.status, "Not recorded")} /><DecisionStatus label="Service eligibility" value={text(asList(asRecord(proposal.commercial_controls).service_eligibility)[0] && asRecord(asList(asRecord(proposal.commercial_controls).service_eligibility)[0]).result, "Not recorded")} /><DecisionStatus label="Policy / capability" value="Configured service catalog"/></div>{ownerRoles.has(role) && <div className="proposal-actions"><button type="button" className="button-secondary" onClick={() => requestAction("Confirm AMEC Scope", "This confirms the AMEC commercial scope. It does not accept the Proposal or authorize release.", "Confirm scope", confirmScope)}>Confirm AMEC Scope</button><button type="button" className="button-secondary" onClick={() => requestAction("Record service eligibility", "This records a governed eligibility decision for the selected offering. It is not an AI recommendation.", "Record eligibility", eligible)}>Record eligible service</button></div>}</StagePanel><ReadinessCard proposal={proposal} role={role} stageNumber={stageNumber} onProceed={() => requestAction("Mark Engineering Ready for Commercial Review", "The confirmed technical package will be handed to Commercial Review. No Proposal acceptance or release occurs.", "Mark engineering ready", ready)} refresh={refresh} /></>;
}

function CommercialStage({ proposal, role, stageNumber, setProposal, setMessage, setError, requestAction, refresh }: StageProps) {
  const fields = proposal.fields; const config = asRecord(proposal.configuration); const template = asRecord(config.proposal_template); const checklist = asRecord(config.proposal_checklist); const accepted = asRecord(proposal.current_revision); const draft = asRecord(proposal.draft_revision); const [price, setPrice] = useState(field(proposal, "price", "")); const [currency, setCurrency] = useState(field(proposal, "currency", "QAR")); const [terms, setTerms] = useState(field(proposal, "payment_terms", ""));
  const save = async () => { try { const result = await api<ProposalDetail>(`/api/bd/proposals/${proposal.id}`, { method: "PATCH", headers: { ...proposalHeaders(role), "Content-Type": "application/json" }, body: JSON.stringify({ fields: { ...fields, price, currency, payment_terms: terms }, expected_updated_at: proposal.updated_at }) }); setProposal(result); setMessage("Commercial basis saved as the working Proposal revision."); } catch (cause: unknown) { setError(cause instanceof Error ? cause.message : "Commercial basis could not be saved."); } };
  const accept = async () => { const result = await proposalCommand<ProposalDetail>(role, proposal.id, "accept"); setProposal(result); setMessage(`Proposal Revision R${text(asRecord(result.current_revision).revision_number)} accepted by a human operator.`); };
  const createRevision = async () => { const result = await proposalCommand<JsonRecord>(role, proposal.id, "revisions", { reason: "New working Proposal revision requested" }); if (result.proposal && typeof result.proposal === "object") setProposal(result.proposal as ProposalDetail); setMessage(`Working Proposal revision R${text(asRecord(result.revision).revision_number)} created from accepted history.`); };
  return <><StagePanel eyebrow="CONFIRMED SCOPE" title="Commercial basis" description="Engineering context is pinned read-only here; commercial changes create a working revision before acceptance."><p className="pinned-context">{text(control(proposal, "scope_confirmation")?.scope_statement, field(proposal, "scope_of_work", "Confirmed scope not recorded"))}</p><div className="proposal-form-grid"><label>AMEC fee<input aria-label="AMEC fee" value={price} onChange={(event) => setPrice(event.target.value)} readOnly={!ownerRoles.has(role)} /></label><label>Currency<select aria-label="Currency" value={currency} onChange={(event) => setCurrency(event.target.value)} disabled={!ownerRoles.has(role)}><option>QAR</option><option>USD</option><option>EUR</option></select></label><label>Payment terms<input aria-label="Payment terms" value={terms} onChange={(event) => setTerms(event.target.value)} readOnly={!ownerRoles.has(role)} /></label><label>Duration<input aria-label="Commercial duration" value={field(proposal, "duration", field(proposal, "period", "Not recorded"))} readOnly /></label></div>{ownerRoles.has(role) && <button type="button" className="button-secondary" onClick={() => void save()}>Save commercial basis</button>}</StagePanel><StagePanel eyebrow="GOVERNED CONTENT" title="Proposal content summary" description="Global master content is consumed, never edited, from this workspace."><div className="content-summary-grid"><ContentLink label="Proposal Template" item={template} /><ContentLink label="Proposal Checklist" item={checklist} /><ContentLink label="Definitions" item={asRecord(config.definitions)} /><ContentLink label="Engineering references" item={asRecord(config.engineering_references)} /></div></StagePanel><StagePanel eyebrow="REVISION / HUMAN ACCEPTANCE" title="Review the exact Proposal revision" description="Accepted history is immutable; working changes remain visible and separate."><div className="revision-summary"><DecisionStatus label="Working revision" value={draft.revision_number ? `R${text(draft.revision_number)}` : "Current working state"}/><DecisionStatus label="Accepted revision" value={accepted.revision_number ? `R${text(accepted.revision_number)}` : "None"}/><DecisionStatus label="Template / checklist" value={`${text(template.ref, "Unresolved")} · ${text(checklist.ref, "Unresolved")}`}/><DecisionStatus label="Warnings" value={`${asList(asRecord(proposal.validation).warnings).length}`}/></div><p className="muted">Accept checks the exact current Proposal revision, source freshness, required fields, and human commercial authority. No Contract or Project is created.</p>{ownerRoles.has(role) && stageNumber !== 1 && <div className="proposal-actions"><button type="button" className="button-primary" onClick={() => requestAction(`Accept Proposal Revision R${text(draft.revision_number || accepted.revision_number || 1)}`, "This freezes the exact current scope, commercial basis, source lineage, and governed content versions into immutable accepted history.", "Accept Proposal revision", accept)} disabled={asList(asRecord(proposal.validation).blockers).length > 0}>Accept Proposal Revision</button>{Boolean(accepted.revision_number) && <button type="button" className="button-secondary" onClick={() => requestAction("Create a new Proposal revision", "This creates a working revision from accepted history. It does not change the accepted revision.", "Create revision", createRevision)}>Create revision</button>}</div>}</StagePanel><ReadinessCard proposal={proposal} role={role} stageNumber={stageNumber} refresh={refresh} /></>;
}

function ClientResponseStage({ proposal, role, stageNumber, setProposal, setMessage, setError, requestAction, refresh }: StageProps) {
  const releaseControl = control(proposal, "commercial_release"); const distribution = control(proposal, "distribution"); const verification = control(proposal, "acceptance_verification"); const lpo = control(proposal, "lpo_reconciliation"); const accepted = asRecord(proposal.current_revision); const responses = asList(asRecord(proposal.hardening).client_responses); const [responseType, setResponseType] = useState("ACCEPTED"); const [responseNotes, setResponseNotes] = useState(""); const [distributionEvidence, setDistributionEvidence] = useState(""); const [acceptanceEvidence, setAcceptanceEvidence] = useState(""); const [lpoEvidence, setLpoEvidence] = useState(""); const [lpoVariance, setLpoVariance] = useState("");
  const command = async (path: string, payload: unknown, message: string) => { const result = await proposalCommand<JsonRecord>(role, proposal.id, path, payload); if (result.proposal && typeof result.proposal === "object") setProposal(result.proposal as ProposalDetail); setMessage(message); };
  const recordResponse = async () => command("client-responses", { response_type: responseType, notes: responseNotes, idempotency_key: `p04-${proposal.id}-${responseType}-${responseNotes}` }, `Client response ${labelize(responseType)} recorded.`);
  const authorizeRelease = async () => command("commercial-release", { accepted_revision_id: accepted.id }, "Commercial release authorized for the exact accepted revision.");
  const distribute = async () => command("distribution", { channel: "CLIENT_PORTAL", evidence_reference: distributionEvidence, recipient: text(asRecord(proposal.forms_v2).proposal_contact, "Client contact") }, "Distribution evidence recorded; sending remains separate from authorization.");
  const verify = async () => { const acceptedResponse = responses.find((item) => text(item.response_type) === "ACCEPTED"); return command("acceptance-verification", { client_response_id: acceptedResponse?.id, evidence_reference: acceptanceEvidence }, "Client acceptance evidence verified by a human operator."); };
  const reconcile = async () => command("lpo-reconciliation", { applies: true, client_artifact_reference: lpoEvidence, variances: lpoVariance.trim() ? [{ field: "commercial_basis", note: lpoVariance.trim() }] : [] }, lpoVariance.trim() ? "PO/LPO reconciliation recorded as a variance." : "PO/LPO reconciliation recorded with zero variances.");
  const createRevision = async () => { const result = await proposalCommand<JsonRecord>(role, proposal.id, "revisions", { reason: "Client Change Requested" }); if (result.proposal && typeof result.proposal === "object") setProposal(result.proposal as ProposalDetail); setMessage("Working revision created from accepted history for client changes."); };
  return <><StagePanel eyebrow="RELEASED BASIS" title="Distribution and client response" description="Record what happened to the exact released Proposal revision; do not conflate sending with acceptance."><div className="decision-grid"><DecisionStatus label="Accepted revision" value={`R${text(accepted.revision_number, "Not accepted")}`} /><DecisionStatus label="Commercial release" value={text(releaseControl?.status, "Not authorized")} /><DecisionStatus label="Distribution" value={distribution ? `${text(distribution.channel)} · evidence retained` : "Not recorded"}/></div>{ownerRoles.has(role) && <div className="proposal-actions"><button type="button" className="button-secondary" onClick={() => requestAction("Authorize Commercial Release", "This authorizes distribution of the exact accepted Proposal revision. It does not claim that the Proposal was sent.", "Authorize release", authorizeRelease)} disabled={!accepted.id}>Authorize Commercial Release</button><label className="proposal-inline-field">Distribution evidence<input value={distributionEvidence} onChange={(event) => setDistributionEvidence(event.target.value)} placeholder="Portal/email/evidence reference" /></label><button type="button" className="button-secondary" onClick={() => requestAction("Record Proposal distribution", "This records the channel, recipient context, and evidence that distribution occurred. It does not verify client acceptance.", "Record distribution", distribute)} disabled={!distributionEvidence.trim()}>Record distribution</button></div>}</StagePanel><StagePanel eyebrow="CLIENT RESPONSE" title="Accepted, rejected, or change requested" description="A Change Requested response routes through a new revision, re-review, re-acceptance, and re-release."><div className="response-history">{responses.length ? responses.map((response, index) => <div key={text(response.id, `response-${index}`)}><span className="proposal-mini-label">{labelize(response.response_type)}</span><b>{text(response.notes, "No notes recorded")}</b><small>{text(response.recorded_by)} · {displayDate(response.recorded_at)} · revision {text(response.accepted_revision_id, "not pinned")}</small></div>) : <div className="proposal-empty-inline">No client response recorded.</div>}</div>{ownerRoles.has(role) && <div className="proposal-inline-form"><select aria-label="Client response type" value={responseType} onChange={(event) => setResponseType(event.target.value)}><option value="ACCEPTED">Accepted</option><option value="DECLINED">Rejected</option><option value="CHANGE_REQUESTED">Change requested</option><option value="EXPIRED">Expired</option><option value="WITHDRAWN">Withdrawn</option></select><input aria-label="Client response notes" value={responseNotes} onChange={(event) => setResponseNotes(event.target.value)} placeholder="Human evidence notes"/><button type="button" className="button-secondary" onClick={() => requestAction(`Record client response: ${labelize(responseType)}`, "This appends a human-recorded external response against the current accepted Proposal revision.", "Record response", recordResponse)}>Record response</button></div>}{responses.some((item) => text(item.response_type) === "CHANGE_REQUESTED") && ownerRoles.has(role) && <button type="button" className="text-button" onClick={() => requestAction("Create revised Proposal", "The accepted revision remains immutable. This creates a working revision for re-review.", "Create revision", createRevision)}>Create revised Proposal for client change</button>}</StagePanel><StagePanel eyebrow="ACCEPTANCE EVIDENCE" title="Verify client acceptance" description="Signed Proposal, PO/LPO, or correspondence must be tied to the accepted revision."><div className="decision-grid"><DecisionStatus label="Acceptance evidence" value={verification ? "VERIFIED" : "Not verified"}/><DecisionStatus label="Client response" value={responses.some((item) => text(item.response_type) === "ACCEPTED") ? "Accepted response recorded" : "Accepted response required"}/><DecisionStatus label="Verification authority" value="Human / server capability"/></div>{ownerRoles.has(role) && <div className="proposal-inline-form"><input aria-label="Client acceptance evidence" value={acceptanceEvidence} onChange={(event) => setAcceptanceEvidence(event.target.value)} placeholder="Signed Proposal / PO / correspondence reference"/><button type="button" className="button-secondary" onClick={() => requestAction("Verify Client Acceptance", "This records human verification of client acceptance against the released Proposal revision. AI cannot perform this action.", "Verify acceptance", verify)} disabled={!acceptanceEvidence.trim()}>Verify Client Acceptance</button></div>}</StagePanel><LpoComparison proposal={proposal} role={role} lpo={lpo} lpoEvidence={lpoEvidence} setLpoEvidence={setLpoEvidence} lpoVariance={lpoVariance} setLpoVariance={setLpoVariance} reconcile={reconcile} requestAction={requestAction} /><IntelligenceUnavailableBoundary items={asList(asRecord(proposal.intelligence).client_response)} /><ReadinessCard proposal={proposal} role={role} stageNumber={stageNumber} refresh={refresh} /></>;
}

function LpoComparison({ proposal, role, lpo, lpoEvidence, setLpoEvidence, lpoVariance, setLpoVariance, reconcile, requestAction }: { proposal: ProposalDetail; role: ProposalRole; lpo: JsonRecord | null; lpoEvidence: string; setLpoEvidence: (value: string) => void; lpoVariance: string; setLpoVariance: (value: string) => void; reconcile: () => Promise<void>; requestAction: (title: string, consequence: string, label: string, action: () => Promise<void>) => void }) {
  const accepted = asRecord(proposal.current_revision); const rows = [{ label: "Scope", accepted: text(control(proposal, "scope_confirmation")?.scope_statement, field(proposal, "scope_of_work")), client: "Enter from PO/LPO" }, { label: "Fee / Value", accepted: `${field(proposal, "price")} ${field(proposal, "currency", "QAR")}`, client: "Enter from PO/LPO" }, { label: "Duration", accepted: field(proposal, "duration", field(proposal, "period")), client: "Enter from PO/LPO" }, { label: "Payment Terms", accepted: field(proposal, "payment_terms"), client: "Enter from PO/LPO" }, { label: "Inclusions / Exclusions", accepted: `${field(proposal, "inclusions")} / ${field(proposal, "exclusions")}`, client: "Enter from PO/LPO" }];
  return <StagePanel eyebrow="PO / LPO RECONCILIATION" title="Structured commercial comparison" description="The backend result is authoritative. A variance blocks Contract handoff and requires a revised Proposal path."><div className="lpo-table-wrap"><table className="lpo-table"><thead><tr><th>Dimension</th><th>Accepted Proposal {accepted.revision_number ? `R${text(accepted.revision_number)}` : "basis"}</th><th>Client PO/LPO</th><th>Backend status</th></tr></thead><tbody>{rows.map((row) => <tr key={row.label}><th>{row.label}</th><td>{row.accepted}</td><td>{row.client}</td><td>{lpo ? text(lpo.result, "Recorded") : "Not reconciled"}</td></tr>)}</tbody></table></div>{lpo?.result === "MISMATCH" && <div className="proposal-alert warning-copy" role="alert"><Icon name="alert" size={16} /> Contract handoff blocked. Create a revised Proposal, re-accept/re-release it, and reconcile the corrected client basis again.</div>}<div className="proposal-inline-form"><input aria-label="LPO evidence reference" value={lpoEvidence} onChange={(event) => setLpoEvidence(event.target.value)} placeholder="PO/LPO evidence reference"/><input aria-label="LPO variance details" value={lpoVariance} onChange={(event) => setLpoVariance(event.target.value)} placeholder="Material variance (leave blank for zero variance)"/><button type="button" className="button-secondary" onClick={() => requestAction("Confirm PO/LPO Reconciliation", "This records the backend reconciliation result against the accepted Proposal revision. It does not accept a Contract.", "Record reconciliation", reconcile)} disabled={!lpoEvidence.trim()}>Record reconciliation</button></div><p className="muted">Final backend result: <b>{text(lpo?.result, "Not reconciled")}</b> · {Array.isArray(lpo?.variances) ? `${lpo?.variances.length} variance(s)` : "variance count unavailable"}</p></StagePanel>;
}

function HandoffStage({ proposal, role, stageNumber, setProposal, setMessage, setError, requestAction, refresh }: StageProps) {
  const controls = asRecord(proposal.commercial_controls); const handoff = control(proposal, "contract_handoff"); const accepted = asRecord(proposal.current_revision); const release = control(proposal, "commercial_release"); const distribution = control(proposal, "distribution"); const verification = control(proposal, "acceptance_verification"); const lpo = control(proposal, "lpo_reconciliation");
  const preview = async () => { const result = await api<JsonRecord>(`/api/bd/proposals/${proposal.id}/handoff/contract`, { headers: proposalHeaders(role) }); setMessage(result.eligible ? "Ready for Contract Handoff." : `Handoff blocked: ${asList(result.blockers).map((item) => text(item.label ?? item)).join(", ")}`); };
  const record = async () => { const result = await proposalCommand<JsonRecord>(role, proposal.id, "handoff/contract-eligibility", {}); if (result.proposal && typeof result.proposal === "object") setProposal(result.proposal as ProposalDetail); setMessage("Contract handoff eligibility recorded. Contract acceptance and Project Activation remain separate."); };
  return <><StagePanel eyebrow="CONTRACT HANDOFF PREFLIGHT" title={handoff ? "Ready for Contract Handoff" : "Handoff preflight"} description="All gates are deterministic and traceable to the accepted Proposal basis."><div className="handoff-gate-list"><Gate label="Accepted Proposal revision" pass={Boolean(accepted.id)} value={accepted.revision_number ? `R${text(accepted.revision_number)}` : "Required"}/><Gate label="Commercial release" pass={Boolean(release)} value={text(release?.status, "Required")}/><Gate label="Distribution evidence" pass={Boolean(distribution)} value={distribution ? "Evidence retained" : "Required"}/><Gate label="Verified client acceptance" pass={Boolean(verification)} value={verification ? "Verified" : "Required"}/><Gate label="PO/LPO reconciliation" pass={Boolean(lpo && ["PASS", "NOT_APPLICABLE"].includes(text(lpo.result))) } value={text(lpo?.result, "Required")}/><Gate label="Scope and governed content" pass={Boolean(control(proposal, "scope_confirmation") && asRecord(proposal.configuration).proposal_template)} value="Current Proposal context"/></div><div className="proposal-actions"><button type="button" className="button-secondary" onClick={() => void preview()}>Preview handoff preflight</button>{ownerRoles.has(role) && <button type="button" className="button-primary" onClick={() => requestAction("Record Contract Handoff Eligibility", "This records eligibility only. It does not create or accept a Contract and does not activate a Project.", "Record handoff eligibility", record)} disabled={!proposal.contract_eligible && !(lpo && ["PASS", "NOT_APPLICABLE"].includes(text(lpo.result)))}>Record Contract Handoff Eligibility</button>}</div></StagePanel><StagePanel eyebrow="DOWNSTREAM BOUNDARY" title="Separate Contract and Project decisions" description="Proposal handoff does not create downstream authority."><div className="boundary-callout"><Icon name="shield" size={18}/><div><b>Contract acceptance: separate decision</b><span>Project Activation: separate explicit Owner action</span><small>Proposal only proves whether the accepted commercial basis is eligible for handoff.</small></div></div></StagePanel><IntelligenceUnavailableBoundary items={asList(asRecord(proposal.intelligence).handoff)} /><ReadinessCard proposal={proposal} role={role} stageNumber={stageNumber} refresh={refresh} /></>;
}

function ReadinessCard({ proposal, role, stageNumber, onProceed, refresh }: { proposal: ProposalDetail; role: ProposalRole; stageNumber: number; onProceed?: () => void; refresh: () => Promise<void> }) { const readiness = asRecord(proposal.intake_readiness); const validation = asRecord(proposal.validation); const blockers = [...asList(readiness.blockers), ...asList(validation.blockers)]; return <StagePanel eyebrow="DETERMINISTIC READINESS" title={blockers.length ? "Action required" : stageNumber === 1 ? "Ready for Engineering" : "No blocking item"} description="Backend readiness is authoritative; no AI determines this state."><div className={blockers.length ? "readiness-blockers" : "readiness-ready"}>{blockers.length ? blockers.map((item, index) => <span key={text(item.code, `blocker-${index}`)}><Icon name="alert" size={14}/>{text(item.label ?? item, "Blocker")}</span>) : <span><Icon name="check" size={14}/>Proposal identity and current evidence remain auditable.</span>}</div>{stageNumber === 1 && onProceed && <button type="button" className="button-primary" onClick={onProceed} disabled={blockers.length > 0 || role === "RESPONSIBLE_ENGINEER"}>Proceed to Engineering Preparation</button>}<button type="button" className="text-button" onClick={() => void refresh()}><Icon name="refresh" size={14}/> Recheck backend readiness</button></StagePanel>; }

function AttentionRail({ proposal, stageNumber, onSelect }: { proposal: ProposalDetail; stageNumber: number; onSelect: (number: number) => void }) { const validation = asRecord(proposal.validation); const blockers = [...asList(asRecord(proposal.intake_readiness).blockers), ...asList(validation.blockers)]; const next = asRecord(proposal.next_action); const controls = asRecord(proposal.commercial_controls); return <aside className="proposal-attention-rail" aria-label="Proposal attention and state"><StagePanel eyebrow="NEXT AUTHORIZED ACTION" title={text(next.label, "Review Proposal")}><p>{text(next.reason, "The backend determines the next action from current business state.")}</p><span className="attention-owner">Current owner · {proposal.current_owner}</span>{typeof next.eligible === "boolean" && <span className={next.eligible ? "attention-ready" : "attention-blocked"}>{next.eligible ? "Eligible" : "Blocked"}</span>}</StagePanel><StagePanel eyebrow="ATTENTION / BLOCKERS" title={blockers.length ? `${blockers.length} item${blockers.length === 1 ? "" : "s"} need attention` : "No current blocker"}>{blockers.length ? <ul className="attention-list">{blockers.map((item, index) => <li key={text(item.code, `rail-blocker-${index}`)}><Icon name="alert" size={14}/>{text(item.label ?? item, "Blocker")}</li>)}</ul> : <p className="muted">The current Proposal can continue according to backend readiness.</p>}</StagePanel><StagePanel eyebrow="PROTECTED STATE" title="Business truth"><div className="rail-state-list"><RailState label="Scope" value={control(proposal, "scope_confirmation") ? "Confirmed" : "Not confirmed"}/><RailState label="Accepted Proposal" value={asRecord(proposal.current_revision).revision_number ? `R${text(asRecord(proposal.current_revision).revision_number)}` : "None"}/><RailState label="Release" value={control(proposal, "commercial_release") ? "Authorized" : "Not released"}/><RailState label="Client acceptance" value={control(proposal, "acceptance_verification") ? "Verified" : "Not verified"}/><RailState label="LPO" value={text(control(proposal, "lpo_reconciliation")?.result, "Not reconciled")}/><RailState label="Contract handoff" value={control(proposal, "contract_handoff") ? "Eligible" : "Not recorded"}/></div></StagePanel><StagePanel eyebrow="INTELLIGENCE STATE" title="Read-only assistance"><p className="muted">No Proposal skill is executable in this environment. There is no active Analyze, Generate, Ask AI, or Review button.</p><button type="button" className="text-button" onClick={() => onSelect(1)}>Open evidence context</button></StagePanel><StagePanel eyebrow="ADVANCED DETAILS" title="Audit identity"><dl className="advanced-details"><div><dt>Proposal ID</dt><dd>{proposal.id}</dd></div><div><dt>Stage code</dt><dd>{proposal.stage}</dd></div><div><dt>Source records</dt><dd>{asList(proposal.sources).length}</dd></div><div><dt>Contract eligible</dt><dd>{proposal.contract_eligible ? "true" : "false"}</dd></div></dl></StagePanel></aside>; }

function DecisionStatus({ label, value }: { label: string; value: string }) { return <div className="decision-status"><span>{label}</span><b>{value}</b></div>; }
function ContentLink({ label, item }: { label: string; item: JsonRecord }) { return <div className="content-summary-item"><Icon name="library" size={16}/><div><b>{label}</b><span>{text(item.ref ?? item.status, "Configuration required")}{item.version ? ` · v${text(item.version)}` : ""}</span><a href="/dashboard">View in Content Library <Icon name="arrow-up-right" size={13}/></a></div></div>; }
function Gate({ label, pass, value }: { label: string; pass: boolean; value: string }) { return <div className={pass ? "handoff-gate pass" : "handoff-gate blocked"}><Icon name={pass ? "check" : "alert"} size={16}/><span><b>{label}</b><small>{value}</small></span></div>; }
function RailState({ label, value }: { label: string; value: string }) { return <div><span>{label}</span><b>{value}</b></div>; }
type StageProps = { proposal: ProposalDetail; role: ProposalRole; stageNumber: number; setProposal: (proposal: ProposalDetail) => void; setMessage: (value: string) => void; setError: (value: string) => void; requestAction: (title: string, consequence: string, label: string, action: () => Promise<void>) => void; refresh: () => Promise<void> };
